package com.wikiponder.touchmap.classes.soundscape;

import android.content.Context;
import android.util.Log;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;

/**
 * Loads the bundled ambient clips (assets/soundscape/*.ogg, generated by
 * tools/generate_soundscape_bank.py from the WAV masters in tools/soundscape_master) as mono 16-bit
 * PCM. Ogg only to keep the APK small; Vorbis decodes sample-exact, so the crossfaded loops stay
 * seamless. Decoding is native (stb_vorbis, see soundscape_jni.cpp) — far faster than MediaCodec.
 */
final class SoundBank {
	private static final String TAG = "SoundBank";
	static final String DIR = "soundscape/";

	static final class Clip {
		final short[] samples;
		final int sampleRate;

		Clip(short[] samples, int sampleRate) {
			this.samples = samples;
			this.sampleRate = sampleRate;
		}
	}

	private SoundBank() {
	}

	/** Returns null (and logs) if the clip is missing or undecodable — the scene just skips it.
	 * Thread-safe. */
	static Clip load(Context context, String id) {
		try (InputStream in = context.getAssets().open(DIR + id + ".ogg")) {
			ByteArrayOutputStream bytes = new ByteArrayOutputStream(256 * 1024);
			byte[] chunk = new byte[64 * 1024];
			int n;
			while ((n = in.read(chunk)) > 0) bytes.write(chunk, 0, n);
			int[] rate = new int[1];
			short[] pcm = SpatialRenderer.decodeOgg(bytes.toByteArray(), rate);
			if (pcm == null) {
				Log.w(TAG, "could not decode " + id);
				return null;
			}
			return new Clip(pcm, rate[0]);
		} catch (IOException e) {
			Log.w(TAG, "missing clip " + id, e);
			return null;
		}
	}
}
